#include <concepts>
#include <cstddef>
#include <iostream>
#include <string>
#include <vector>

template<class T>
concept HasSize = requires(const T& value) {
    { value.size() } -> std::convertible_to<std::size_t>;
};

template<HasSize T>
void print_size(const T& value)
{
    std::cout << static_cast<std::size_t>(value.size()) << '\n';
}

int main()
{
    static_assert(HasSize<std::string>);
    static_assert(!HasSize<int>);
    print_size(std::string{"Atlas"});
    print_size(std::vector<int>{2, 4, 6});
}
